(function(root){
  'use strict';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function html(state){return `<section class="intro"><p class="eyebrow">MY EQUIPMENT</p><div class="row between wrap"><h1>수렵한 방어구 세트</h1><div class="row wrap"><button id="export-data">JSON 백업</button><button id="import-data">백업 불러오기</button></div></div><p>수렵을 마친 세트를 체크하세요. 체크된 세트만 조합 검색에 포함합니다.</p></section><div class="subnav"><button data-etab="weapons">무기 ${state.weapons.length}</button><button data-etab="charms">호석 ${state.charms.length}</button><button data-etab="customArmor" class="active">방어구 해금</button></div><section class="panel"><div class="row between wrap"><h2>세트별 수렵 완료</h2><span class="badge gold">한계돌파 · 최대 강화 완료 기준</span></div><p class="hint" style="margin:.6rem 0 1rem">기본값은 전체 체크입니다. 한계돌파가 가능한 방어구에는 돌파 후 슬롯과 최대 방어력을 적용합니다.</p><div class="tab-toolbar"><input id="armor-set-query" placeholder="세트 이름 검색 · 예: 고그" aria-label="방어구 세트 검색"><select id="armor-set-rank" aria-label="세트 등급"><option value="all">상위 + 하위</option><option value="high">상위</option><option value="low">하위</option></select><select id="armor-set-sort" aria-label="방어구 정렬"><option value="rarity-desc">레어도 높은순</option><option value="rarity-asc">레어도 낮은순</option><option value="name-asc">가나다순</option><option value="name-desc">가나다 역순</option></select><button id="armor-sets-enable">표시된 세트 전체 체크</button><button id="armor-sets-disable">표시된 세트 전체 해제</button></div><p id="armor-set-count" class="hint" role="status"></p><div id="armor-set-list" class="armor-set-grid"></div></section>`;}
  function mount({db,getExcluded,onChange}){
    const A=root.WildsArmorAccess,sets=A.groups(db),$=s=>document.querySelector(s);let query='',rank='all',sort='rarity-desc';
    const byName=(a,b)=>a.name.localeCompare(b.name,'ko')||a.rank.localeCompare(b.rank)||a.id.localeCompare(b.id);
    const orders={'rarity-desc':(a,b)=>b.rarity-a.rarity||byName(a,b),'rarity-asc':(a,b)=>a.rarity-b.rarity||byName(a,b),'name-asc':byName,'name-desc':(a,b)=>-byName(a,b)};
    const filtered=()=>sets.filter(s=>(rank==='all'||s.rank===rank)&&s.name.normalize('NFKC').replaceAll(' ','').toLowerCase().includes(query.normalize('NFKC').replaceAll(' ','').toLowerCase())).sort(orders[sort]);
    function render(){const blocked=new Set(getExcluded()),visible=filtered(),enabled=sets.filter(s=>s.armorIds.every(id=>!blocked.has(id)));$('#armor-set-count').textContent=`전체 ${sets.length}세트 중 ${enabled.length}세트 포함 · 방어구 ${db.armor.length-blocked.size}부위 / 현재 ${visible.length}세트 표시`;$('#armor-set-list').innerHTML=visible.length?visible.map(s=>{const checked=s.armorIds.every(id=>!blocked.has(id));return `<label class="armor-set-card ${checked?'':'excluded'}"><input type="checkbox" class="armor-set-check" data-set-id="${esc(s.id)}" ${checked?'checked':''}><span><strong>${esc(s.name)}</strong><small>${s.rank==='high'?'상위':'하위'} · RARE ${s.rarity} · ${s.armorIds.length}부위</small></span><span class="armor-set-status">${checked?'수렵 완료':'미수렵'}</span></label>`;}).join(''):'<p class="hint">일치하는 세트가 없습니다.</p>';for(const c of document.querySelectorAll('.armor-set-check'))c.onchange=()=>{onChange(A.setEnabled(db,getExcluded(),[c.dataset.setId],c.checked));render();};}
    $('#armor-set-sort').onchange=e=>{sort=e.target.value;render();};$('#armor-set-query').oninput=e=>{query=e.target.value;render();};$('#armor-set-rank').onchange=e=>{rank=e.target.value;render();};$('#armor-sets-enable').onclick=()=>{onChange(A.setEnabled(db,getExcluded(),filtered().map(s=>s.id),true));render();};$('#armor-sets-disable').onclick=()=>{onChange(A.setEnabled(db,getExcluded(),filtered().map(s=>s.id),false));render();};render();
  }
  root.WildsArmorUnlocks={html,mount};
})(globalThis);
